INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind Performance-Tests nur für fertige Systeme nötig?', 2, '[{"text": "Nein", "correct": true, "because": "Auch während Entwicklung hilfreich"}, {"text": "Ja", "correct": false, "because": "Frühzeitige Tests sinnvoll"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Performance-Tests?', 3, '[{"text": "Geschwindigkeit optimieren", "correct": true, "because": "Laufzeit messen"}, {"text": "Fehler finden", "correct": false, "because": "Funktionstest-Fokus"}, {"text": "UI verbessern", "correct": false, "because": "Kein Design-Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Arten von Performance-Tests sind essenziell?', 5, '[{"text": "Lasttests", "correct": true, "because": "Simuliert hohe Nutzung"}, {"text": "Stresstests", "correct": true, "because": "Prüft Grenzen"}, {"text": "Unit-Tests", "correct": false, "because": "Funktionalität prüfen"}, {"text": "UI-Tests", "correct": false, "because": "Design-Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Lasttests simulieren Nutzer. b) Sie ersetzen Funktionstests.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Funktionstests separat"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei Performance-Tests?', 4, '[{"text": "Laufzeit", "correct": false, "because": "Kern der Messung"}, {"text": "Ressourcennutzung", "correct": false, "because": "Wichtige Metrik"}, {"text": "Farbschema", "correct": true, "because": "Kein Performance-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Performance-Tests immer teuer sind?', 2, '[{"text": "Nein", "correct": true, "because": "Tools können kostengünstig sein"}, {"text": "Ja", "correct": false, "because": "Kosten variieren"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Tool eignet sich für Lasttests?', 3, '[{"text": "JMeter", "correct": true, "because": "Simuliert Nutzerlast"}, {"text": "JUnit", "correct": false, "because": "Unit-Tests"}, {"text": "Selenium", "correct": false, "because": "UI-Tests"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Metriken messe ich bei Performance-Tests?', 5, '[{"text": "Antwortzeit", "correct": true, "because": "Zeigt Geschwindigkeit"}, {"text": "CPU-Auslastung", "correct": true, "because": "Ressourcen prüfen"}, {"text": "Code-Zeilen", "correct": false, "because": "Kein Performance-Maß"}, {"text": "Farbtiefe", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Performance-Tests finden Bottlenecks. b) Sie garantieren Fehlerfreiheit. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Fehlerfreiheit nicht Ziel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Performance-Tests?', 4, '[{"text": "Testumgebung", "correct": false, "because": "Simuliert Realität"}, {"text": "Metriken", "correct": false, "because": "Ergebnisse messen"}, {"text": "Grafikdesign", "correct": true, "because": "Kein Testfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Performance-Tests nur für Server?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Clients testen"}, {"text": "Ja", "correct": false, "because": "Systemweit relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen Performance-Tests?', 4, '[{"text": "Nutzersimulation", "correct": true, "because": "Last erzeugen"}, {"text": "Hardware", "correct": true, "because": "Ressourcen bestimmen"}, {"text": "UI-Layout", "correct": false, "because": "Kein Performance-Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Performance-Tests nur Laufzeit messen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Ressourcen prüfen"}, {"text": "Ja", "correct": false, "because": "Umfassender"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei Performance-Tests?', 3, '[{"text": "Realistische Szenarien", "correct": true, "because": "Spiegelt Nutzung wider"}, {"text": "Schnelle Durchführung", "correct": false, "because": "Genauigkeit zählt"}, {"text": "Viele Tester", "correct": false, "because": "Automatisierung besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Stresstests prüfen Grenzen. b) Sie ersetzen Lasttests.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Lasttests separat"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Probleme decken Performance-Tests auf?', 5, '[{"text": "Bottlenecks", "correct": true, "because": "Zeigt Engpässe"}, {"text": "Skalierungsfehler", "correct": true, "because": "Lastverhalten prüfen"}, {"text": "Syntaxfehler", "correct": false, "because": "Code-Fokus"}, {"text": "UI-Bugs", "correct": false, "because": "Design-Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Performance-Tests unwichtig?', 3, '[{"text": "Antwortzeit", "correct": false, "because": "Kernmetrik"}, {"text": "Lastsimulation", "correct": false, "because": "Realität prüfen"}, {"text": "Schriftart", "correct": true, "because": "Kein Performance-Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ersetzen Performance-Tests Unit-Tests?', 3, '[{"text": "Nein", "correct": true, "because": "Anderer Fokus"}, {"text": "Ja", "correct": false, "because": "Ergänzen sich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Performance-Tests Cloud-Systeme prüfen können?', 2, '[{"text": "Ja", "correct": true, "because": "Skalierung testen"}, {"text": "Nein", "correct": false, "because": "Cloud-relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ergebnis erwarte ich von Performance-Tests?', 4, '[{"text": "Optimierungspotenziale", "correct": true, "because": "Schwachstellen zeigen"}, {"text": "Fehlerfreiheit", "correct": false, "because": "Anderer Test"}, {"text": "UI-Verbesserung", "correct": false, "because": "Kein Design-Fokus"}]');
